genericcontrol.script:
-- The pill is built from three tinted bitmap widgets rather than
-- a 9-slice frame: widgets take an explicit draw size, so the art
-- can be authored at 3x and downsampled (frames draw their border
-- bands 1:1, so a bigger bitmap there just means a bigger pill),
-- and widgets can be tinted, so one white shape serves every
-- style. The caps keep their aspect and only the middle stretches.
local HEIGHT = 14;
local PADDING = 6;     -- each side of the label
local CAP_ART = "graphics/frames/cc_tag_left.png";
local CAP_FALLBACK = 7;

-- Caps are drawn at the same scale horizontally as vertically,
-- or their curve distorts, so the draw width follows the art's
-- own aspect: measured once at runtime, so re-exporting the art
-- at a different aspect needs no code change. (No library calls
-- at file scope here — a control script has no `math` until its
-- functions run.)
local _nCap = nil;
local function getCapWidth()
	if _nCap then
		return _nCap;
	end
	local nW, nH;
	if Interface and Interface.getAssetSize then
		nW, nH = Interface.getAssetSize(CAP_ART);
	end
	nW, nH = tonumber(nW) or 0, tonumber(nH) or 0;
	if (nW > 0) and (nH > 0) then
		_nCap = math.floor(((HEIGHT * nW) / nH) + 0.5);
	else
		_nCap = CAP_FALLBACK;
	end
	_nCap = math.max(_nCap, 2);
	return _nCap;
end

-- sPill tints the shape, sLabel the text on top of it.
local _tStyles = {
	red = { sPill = "FFB22E2E", sLabel = "FFFFFFFF" },
	green = { sPill = "FF55A000", sLabel = "FFFFFFFF" },
	neutral = { sPill = "FFD8D2BD", sLabel = "FF1A1A1A" },
};

-- Created in draw order: shape first, label last (on top).
local _wLeft, _wMiddle, _wRight, _wLabel = nil, nil, nil, nil;

function setText(sText, sStyle)
	if (sText or "") == "" then
		setVisible(false);
		-- collapse so empty chip rows don't inflate the card
		setAnchoredHeight(0);
		setAnchoredWidth(0);
		return;
	end
	local tStyle = _tStyles[sStyle or ""] or _tStyles["neutral"];

	local nCap = getCapWidth();
	if not _wLeft then
		-- w/h are the draw size, which is what lets the art be
		-- authored larger and be downsampled here.
		_wLeft = addBitmapWidget({ icon = "cc_tag_left", w = nCap, h = HEIGHT });
		_wMiddle = addBitmapWidget({ icon = "cc_tag_middle", w = nCap, h = HEIGHT });
		_wRight = addBitmapWidget({ icon = "cc_tag_right", w = nCap, h = HEIGHT });
		_wLabel = addTextWidget({ font = "cc_chip", text = sText, position = "center" });
	else
		_wLabel.setText(sText);
	end

	-- Measure the label, then lay the three pieces out around it.
	_wLabel.setColor(tStyle.sLabel);
	local nWidth = math.max((_wLabel.getSize() or 24) + (PADDING * 2), (nCap * 2) + 2);
	local nMiddle = nWidth - (nCap * 2);

	_wLeft.setSize(nCap, HEIGHT);
	_wLeft.setPosition("topleft", nCap / 2, HEIGHT / 2);
	_wMiddle.setSize(nMiddle, HEIGHT);
	_wMiddle.setPosition("topleft", nCap + (nMiddle / 2), HEIGHT / 2);
	_wRight.setSize(nCap, HEIGHT);
	_wRight.setPosition("topleft", nWidth - (nCap / 2), HEIGHT / 2);
	for _, w in ipairs({ _wLeft, _wMiddle, _wRight }) do
		w.setColor(tStyle.sPill);
	end

	setAnchoredWidth(nWidth);
	setAnchoredHeight(HEIGHT);
	setVisible(true);
end
